import { ArrowCirclepathReverseIcon } from '@navikt/aksel-icons';
import { Box, Button, HStack, Search, UNSAFE_Combobox, VStack } from '@navikt/ds-react';
import { getRouteApi } from '@tanstack/react-router';
import dayjs from 'dayjs';
import { atom, useAtom, useAtomValue, useSetAtom } from 'jotai';
import { atomWithReset, RESET, useHydrateAtoms } from 'jotai/utils';
import { debounce, xor } from 'lodash';
import { useCallback, useEffect, useRef, useState } from 'react';
import { getOptionFromPeriod } from 'src/components/DateFilters/DatePeriodSelector';
import { DateRangePickerWithDebounce } from 'src/components/DateFilters/DateRangePickerWithDebounce';
import { type DateRange, PeriodType } from 'src/components/DateFilters/types';
import { TemaFilterKort } from 'src/components/Dokumenter/TemaFilterKort';
import {
    avsenderLabel,
    useAvsendereForPeriode,
    useTemaDokumentStatistikk,
    useTemaerForPeriode
} from 'src/components/Dokumenter/utils';
import { FeatureToggles } from 'src/components/featureToggle/toggleIDs';
import QueryErrorBoundary from 'src/components/QueryErrorBoundary';
import type { DokumentmetadataAvsender } from 'src/generated/modiapersonoversikt-api';
import { aktivBrukerLastetAtom, usePersonAtomValue } from 'src/lib/state/context';
import featuretoggles from 'src/rest/resources/featuretogglesResource';
import { filterType, trackFilterEndret } from 'src/utils/analytics';

const routeApi = getRouteApi('/new/person/dokumenter');

export type DokumenterFilter = {
    dateRange: DateRange | null;
    periodType: PeriodType;
    temaer: string[];
    avsendere: DokumentmetadataAvsender[];
    saksId?: string;
};

export const dokumenterFilterAtom = atomWithReset<DokumenterFilter>({
    dateRange: null,
    temaer: [],
    avsendere: [],
    saksId: '',
    periodType: PeriodType.UNSET
});

const dokFilterTemaAtom = atom(
    (get) => get(dokumenterFilterAtom).temaer,
    (_get, set, newVal: string) => {
        set(dokumenterFilterAtom, (filters) => ({
            ...filters,
            temaer: filters.temaer ? xor(filters.temaer, [newVal]) : [newVal]
        }));
    }
);

const dokFilterAvsenderAtom = atom(
    (get) => get(dokumenterFilterAtom).avsendere,
    (_get, set, newVal: DokumentmetadataAvsender) => {
        set(dokumenterFilterAtom, (filters) => ({
            ...filters,
            avsendere: filters.avsendere ? xor(filters.avsendere, [newVal]) : [newVal]
        }));
    }
);

const dokFilterSaksIdAtom = atom(
    (get) => get(dokumenterFilterAtom).saksId,
    (_get, set, newVal: string) => {
        set(dokumenterFilterAtom, (filters) => ({
            ...filters,
            saksId: newVal.length ? newVal : undefined
        }));
    }
);

const dokFilterDateRangeAtom = atom(
    (get) => get(dokumenterFilterAtom).dateRange,
    (_get, set, dateRange: DateRange | null) => {
        set(dokumenterFilterAtom, (filters) => ({
            ...filters,
            dateRange
        }));
    }
);

const dokFilterPeriodType = atom(
    (get) => get(dokumenterFilterAtom).periodType,
    (_get, set, type: PeriodType) => {
        set(dokumenterFilterAtom, (filters) => ({
            ...filters,
            periodType: type
        }));
    }
);

const SaksIdSearchField = () => {
    const [internalValue, setInternalValue] = useState('');
    const [value, setValue] = useAtom(dokFilterSaksIdAtom);
    const navigate = routeApi.useNavigate();

    useEffect(() => {
        setInternalValue(value ?? '');
    }, [value]);

    const setValueOgTrackSok = (v: string) => {
        setValue(v);
        navigate({ search: { saksid: v } });
        trackFilterEndret('dokumenter', filterType.SOK);
    };

    const setAtomValue = debounce(setValueOgTrackSok, 500);
    return (
        <Search
            size="small"
            label="Saksnummer"
            variant="secondary"
            hideLabel={false}
            value={internalValue}
            onChange={(v) => {
                setInternalValue(v);
                setAtomValue(v);
            }}
        />
    );
};

const DateFilter = () => {
    const [value, setValue] = useAtom(dokFilterDateRangeAtom);
    const [periodType, setPeriodType] = useAtom(dokFilterPeriodType);
    const navigate = routeApi.useNavigate();

    const onChange = (range?: DateRange) => {
        setValue(range ?? null);
        navigate({
            search: {
                fra: range?.from ? range?.from.format('DD.MM.YYYY').toString() : '',
                til: range?.to ? range?.to.format('DD.MM.YYYY').toString() : ''
            }
        });
    };
    return (
        <DateRangePickerWithDebounce
            period={periodType}
            onPeriodChange={setPeriodType}
            dateRange={value}
            onRangeChange={onChange}
            allowUnset
        />
    );
};

const NyttTemaFilter = () => {
    const navigate = routeApi.useNavigate();
    const { temaer, dataLoaded } = useTemaDokumentStatistikk();
    const selectedTemaer = useAtomValue(dokFilterTemaAtom);
    const setFilter = useSetAtom(dokumenterFilterAtom);

    useEffect(() => {
        if (!dataLoaded) return;
        const gyldigeTemaKoder = new Set(temaer.map((tema) => tema.temakode));
        const gyldigeValg = selectedTemaer.filter((tema) => gyldigeTemaKoder.has(tema));
        if (gyldigeValg.length !== selectedTemaer.length) {
            setFilter((prev) => ({ ...prev, temaer: gyldigeValg }));
            navigate({ search: { tema: gyldigeValg }, replace: true });
        }
    }, [temaer, dataLoaded, selectedTemaer, setFilter, navigate]);

    const onChange = useCallback(
        (newTemaer: string[]) => {
            setFilter((prev) => ({ ...prev, temaer: newTemaer }));
            trackFilterEndret('dokumenter', filterType.TEMA);
            navigate({ search: { tema: newTemaer } });
        },
        [navigate, setFilter]
    );

    return (
        <TemaFilterKort temaer={temaer} selectedTemaer={selectedTemaer} onChange={onChange} dataLoaded={dataLoaded} />
    );
};

const GammeltTemaFilter = () => {
    const navigate = routeApi.useNavigate();
    const dateRange = useAtomValue(dokFilterDateRangeAtom);
    const alleTemaer = useTemaerForPeriode(dateRange);
    const [selectedTemaer, setSelectedTemaer] = useAtom(dokFilterTemaAtom);
    const setFilter = useSetAtom(dokumenterFilterAtom);

    useEffect(() => {
        const gyldigeTemaKoder = new Set(alleTemaer.map((tema) => tema.temakode));
        const gyldigeValg = selectedTemaer.filter((tema) => gyldigeTemaKoder.has(tema));
        if (gyldigeValg.length !== selectedTemaer.length) {
            setFilter((prev) => ({ ...prev, temaer: gyldigeValg }));
            navigate({ search: { tema: gyldigeValg } });
        }
    }, [alleTemaer, selectedTemaer, setFilter, navigate]);

    const onToggleSelected = useCallback(
        (option: string) => {
            setSelectedTemaer(option);
            trackFilterEndret('dokumenter', filterType.TEMA);
            navigate({ search: { tema: selectedTemaer ? xor(selectedTemaer, [option]) : [option] } });
        },
        [selectedTemaer, setSelectedTemaer, navigate]
    );

    return (
        <UNSAFE_Combobox
            size="small"
            label="Tema"
            options={alleTemaer.map((tema) => ({
                label: `${tema.temanavn} [${tema.temakode}]`,
                value: tema.temakode
            }))}
            isMultiSelect
            selectedOptions={selectedTemaer}
            onToggleSelected={onToggleSelected}
        />
    );
};

const AvsenderFilter = () => {
    const navigate = routeApi.useNavigate();
    const dateRange = useAtomValue(dokFilterDateRangeAtom);
    const alleAvsendere = useAvsendereForPeriode(dateRange);
    const [selectedAvsendere, setSelectedAvsendere] = useAtom(dokFilterAvsenderAtom);
    const setFilter = useSetAtom(dokumenterFilterAtom);

    useEffect(() => {
        const gyldigeAvsendere = new Set(alleAvsendere);
        const gyldigeValg = selectedAvsendere.filter((a) => gyldigeAvsendere.has(a));
        if (gyldigeValg.length !== selectedAvsendere.length) {
            setFilter((prev) => ({ ...prev, avsendere: gyldigeValg }));
            navigate({ search: { avsendere: gyldigeValg } });
        }
    }, [alleAvsendere, selectedAvsendere, setFilter, navigate]);

    const onToggleSelected = useCallback(
        (option: string) => {
            const avsender = option as DokumentmetadataAvsender;
            setSelectedAvsendere(avsender);
            trackFilterEndret('dokumenter', filterType.AVSENDER);
            navigate({
                search: { avsendere: selectedAvsendere ? xor(selectedAvsendere, [avsender]) : [avsender] }
            });
        },
        [selectedAvsendere]
    );

    return (
        <UNSAFE_Combobox
            size="small"
            label="Avsender"
            options={alleAvsendere.map((avsender) => ({
                label: avsenderLabel[avsender],
                value: avsender
            }))}
            isMultiSelect
            selectedOptions={selectedAvsendere.map((avsender) => ({
                label: avsenderLabel[avsender],
                value: avsender
            }))}
            onToggleSelected={onToggleSelected}
        />
    );
};

const ResetFilter = () => {
    const [filter, setFilter] = useAtom(dokumenterFilterAtom);
    const navigate = routeApi.useNavigate();

    const datoErlik = filter.dateRange === null;
    const isDirty = !filter.temaer.isEmpty() || !filter.avsendere.isEmpty() || !!filter.saksId || !datoErlik;

    const resetFilter = () => {
        setFilter(RESET);
        navigate({ search: { tema: [], avsendere: [], saksid: '', fra: '', til: '' }, replace: true });
    };

    return (
        <Button
            icon={<ArrowCirclepathReverseIcon aria-hidden />}
            disabled={!isDirty}
            onClick={() => resetFilter()}
            variant="tertiary"
            size="small"
        >
            Tilbakestill
        </Button>
    );
};

export const DokumenterFilter = () => {
    const setFilter = useSetAtom(dokumenterFilterAtom);
    const queries = routeApi.useSearch();
    const fnr = usePersonAtomValue();
    const aktivBrukerLastet = useAtomValue(aktivBrukerLastetAtom);
    const { data: toggles, isLoading: lasterToggles, error: toggleFeil } = featuretoggles.useFetch();
    const prevFnrRef = useRef<string | undefined>(undefined);
    const dateRange: DateRange | null =
        queries.fra && queries.til
            ? {
                  from: dayjs(queries.fra, 'DD.MM.YYYY'),
                  to: dayjs(queries.til, 'DD.MM.YYYY')
              }
            : null;

    useHydrateAtoms([
        [
            dokumenterFilterAtom,
            {
                dateRange: dateRange,
                temaer: queries.tema ?? [],
                avsendere: queries.avsendere ?? [],
                saksId: queries.saksid ?? '',
                periodType: dateRange ? getOptionFromPeriod(dateRange) : PeriodType.UNSET
            }
        ]
    ]);

    // Brukes for å sette filteret ved navigasjon fra bla. hjemsiden
    useEffect(() => {
        setFilter({
            dateRange,
            temaer: queries.tema ?? [],
            avsendere: queries.avsendere ?? [],
            saksId: queries.saksid ?? '',
            periodType: dateRange ? getOptionFromPeriod(dateRange) : PeriodType.UNSET
        });
    }, [queries.tema?.join(','), queries.avsendere?.join(','), queries.saksid, queries.fra, queries.til]);

    useEffect(() => {
        if (!aktivBrukerLastet) return;
        const prev = prevFnrRef.current;
        if (prev !== fnr) {
            prevFnrRef.current = fnr;
            if (prev !== undefined) {
                setFilter(RESET);
            }
        }
    }, [fnr, aktivBrukerLastet, setFilter]);

    if (lasterToggles || toggleFeil) {
        return <QueryErrorBoundary loading={lasterToggles} error={toggleFeil} />;
    }

    if (toggles?.[FeatureToggles.NyttDokumentTemaFilter] === true) {
        return (
            <VStack gap="space-16">
                <NyttTemaFilter />
                <HStack gap="space-8" justify="start">
                    <Box>
                        <DateFilter />
                    </Box>
                    <Box flexGrow="1">
                        <AvsenderFilter />
                    </Box>
                    <Box>
                        <SaksIdSearchField />
                    </Box>
                    <HStack align="end">
                        <ResetFilter />
                    </HStack>
                </HStack>
            </VStack>
        );
    }

    return (
        <HStack gap="space-8" justify="start">
            <Box>
                <DateFilter />
            </Box>
            <Box flexGrow="1">
                <AvsenderFilter />
            </Box>
            <Box flexGrow="1">
                <GammeltTemaFilter />
            </Box>
            <Box>
                <SaksIdSearchField />
            </Box>
            <HStack align="end">
                <ResetFilter />
            </HStack>
        </HStack>
    );
};
